+
+/// The lowest Z of the block's corners as `a` holds them.
+fn low(a: Location) -> f64 {
+    (0..8)
+        .map(|i| at(a, [f64::from(i & 1) * 20.0, f64::from((i >> 1) & 1) * 20.0, f64::from(i >> 2) * 10.0])[2])
